// some stochastic pixelsort snow...

#define VidTex iChannel1
#define RandTex iChannel2

float Br(vec4 c) { return dot(c.xyz,vec3(1)); }

vec4 MyMax(vec4 c1, vec4 c2) { return (Br(c1)>Br(c2))?c1:c2; }

void mainImage( out vec4 fragColor, vec2 fragCoord )
{
    vec2 Res=vec2(textureSize(iChannel3,0));
    Res=iResolution.xy;
    vec2 uv = fragCoord.xy / Res;
    ivec2 fci=ivec2(fragCoord);
    vec4 r=texelFetch(RandTex,(fci+iFrame*ivec2(17,37))%256,0);
    vec4 ry=texelFetch(RandTex,(ivec2(0,fci.y)+iFrame*ivec2(17,37))%256,0);
    vec4 c0 = texelFetch(iChannel3,fci,0);

    int delta=int(ry.z*(iResolution.x*.5));
    ivec2 fci0=fci; fci0.x=fci0.x/delta*delta;
    int s=0; if(fci.x-fci0.x>=delta/2) s=1;
    vec4 c1  = texelFetch(iChannel3,fci+(1-s*2)*ivec2(delta/2,0),0);

    bool doSort=fract(iTime/6.)>.5;
    float doSortFact=sin(iTime*2.)*.4+.4+.2;
    doSort=doSortFact>ry.w;
    if(doSort)
    {
        if(Br(c1)> Br(c0) && s==0) c0=c1;
        if(Br(c1)<=Br(c0) && s==1) c0=c1;
    }

    fragColor = c0;

    vec4 cv=texture(VidTex,uv);
    cv=mix(cv,vec4(0),dot(cv.xyz,vec3(-1,1.8,-1)));

    if(!doSort)
    if((iFrame+fci.y*17+fci.x*11)%5==0 && (iFrame%3)==0)
        fragColor=mix(fragColor,cv,clamp(cv*2.,0.,1.));
    fragColor-=(1.-doSortFact)*.015;
    fragColor.w=1.;
}
